     3	/**
     4	 * A policy the MHPCO has issued over a list of insured items: what the office
     5	 * covers, and what the covered items are insured for.
     6	 *
     7	 * How far beyond the insurance sum the office will pay out is a separate
     8	 * decision, made by {@link PayoutCap}.
     9	 */
    10	public final class Policy {
    11	
    12	    private final List<Item> insuredItems;
    13	
    14	    public Policy(List<Item> insuredItems) {
    15	        this.insuredItems = List.copyOf(insuredItems);
    16	    }
    17	
    18	    /**
    19	     * What the covered items are insured for, all together: each item at its
    20	     * own insurance value, summed. What the MHPCO charged to insure them does
    21	     * not enter into it -- neither a risk surcharge nor the component block
    22	     * offer moves the insurance sum.
    23	     */
    24	    public int insuranceSum() {
    25	        return insuredItems.stream()
    26	                .mapToInt(InsuranceValues::insuranceValueOf)
    27	                .sum();
    28	    }
    29	
    30	    /**
    31	     * The most the MHPCO will pay out over the life of this policy. No claim
    32	     * has yet been made against a policy, so this is the whole cap; what
    33	     * remains of it after claims is a claim's concern.
    34	     */
    35	    public int cap() {
    36	        return PayoutCap.overInsuranceSum(insuranceSum());
    37	    }
    38	
    39	    /**
    40	     * The MHPCO settles an incident against this policy: it reimburses the
    41	     * incident and reports what the settlement leaves of the policy's cap.
    42	     */
    43	    public Claim claim(Incident incident) {
    44	        int payout = Reimbursement.forIncident(incident, this::damagedItem);
    45	        return new Claim(payout, cap() - payout);
    46	    }
    47	
    48	    /**
    49	     * The insured item a reported damage was suffered by, found among the
    50	     * items this policy covers.
    51	     */
    52	    private Item damagedItem(Damage damage) {
    53	        return insuredItems.stream()
    54	                .filter(item -> item.type().equals(damage.itemType()))
    55	                .findFirst()
    56	                .orElseThrow();
    57	    }
    58	}
===== PayoutCap =====
     1	/**
     2	 * The most the MHPCO will pay out over the life of a policy: twice the
     3	 * insurance sum of the items it covers.
     4	 *
     5	 * This is the one place that decides the office's payout ceiling. It is a
     6	 * separate decision from what the covered items are insured for: the MHPCO may
     7	 * revalue the items it covers without changing how far it will go beyond that
     8	 * value, and may change how far it will go without revaluing anything.
     9	 */
    10	public final class PayoutCap {
    11	
    12	    private static final int CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
    13	
    14	    private PayoutCap() {
    15	    }
    16	
    17	    public static int overInsuranceSum(int insuranceSumInG) {
    18	        return CAP_MULTIPLE_OF_INSURANCE_SUM * insuranceSumInG;
    19	    }
    20	}
===== Coverage =====
     1	/**
     2	 * What a policy covers, as a reimbursement needs to see it: which insured
     3	 * item a reported damage was suffered by.
     4	 *
     5	 * Reimbursing a damage depends on the item that suffered it -- its
     6	 * enchantment, its material -- but not on how a policy decides which of its
     7	 * covered items that is -- by type today, by an item the damage names
     8	 * outright tomorrow. This is the name of that dependency, so the office's
     9	 * reimbursement clauses and a policy's record of what it covers change for
    10	 * their own reasons.
    11	 *
    12	 * Not to be confused with {@link InsurableItems}, which decides what the
    13	 * office will take on at all; this says what one issued policy already
    14	 * covers.
    15	 */
    16	@FunctionalInterface
    17	public interface Coverage {
    18	
    19	    /**
    20	     * The insured item the reported damage was suffered by.
    21	     */
    22	    Item damagedIn(Damage damage);
    23	}
===== Reimbursement =====
     1	import java.math.BigDecimal;
     2	
     3	/**
     4	 * What the MHPCO reimburses for reported damage: the amount it reimburses for
     5	 * the damage, less the deductible that applies per damage event.
     6	 *
     7	 * This is the one place that says how much an incident is worth to the
     8	 * claimant. How far the MHPCO will actually go in paying that -- what the
     9	 * policy's cap leaves of it -- is a separate decision, made where the policy
    10	 * settles the claim.
    11	 */
    12	public final class Reimbursement {
    13	
    14	    private static final int DEDUCTIBLE_PER_DAMAGE_IN_G = 100;
    15	
    16	    /**
    17	     * The enchantment level from which the MHPCO reimburses damage at half.
    18	     * It is not the level from which the office charges a high-enchantment
    19	     * risk surcharge on a premium: the office decides what it considers risky
    20	     * enough to charge extra for, and what it considers volatile enough to
    21	     * reimburse only in part, for separate reasons and at separate levels.
    22	     */
    23	    private static final int VOLATILE_ENCHANTMENT_LEVEL = 8;
    24	
    25	    private static final int VOLATILE_ITEM_REIMBURSEMENT_PERCENT = 50;
    26	
    27	    private Reimbursement() {
    28	    }
    29	
    30	    /**
    31	     * An incident is reimbursed damage by damage: the office settles each
    32	     * reported damage on its own and pays the sum, because the deductible is
    33	     * charged per damage event rather than once for the incident.
    34	     *
    35	     * The MHPCO keeps intermediate amounts as fractions and rounds only the
    36	     * final payout, so each damage is settled as a fraction and the sum is
    37	     * narrowed to whole G once, here. No active example yields a fractional
    38	     * payout, so that narrowing is exact today; how the office rounds one
    39	     * that is not -- in its own favour, down -- is a decision no active
    40	     * behaviour has asked for, and this is where it will be made.
    41	     */
    42	    public static int forIncident(Incident incident, Coverage coverage) {
    43	        return incident.damages().stream()
    44	                .map(damage -> forDamage(damage, coverage.damagedIn(damage)))
    45	                .reduce(BigDecimal.ZERO, BigDecimal::add)
    46	                .intValueExact();
    47	    }
    48	
    49	    /**
    50	     * One reported damage is settled in two steps the MHPCO decides
    51	     * separately: how much of the damage it reimburses at all, and then the
    52	     * deductible it charges for the damage event.
    53	     */
    54	    private static BigDecimal forDamage(Damage damage, Item damagedItem) {
    55	        return reimbursableAmount(damage, damagedItem)
    56	                .subtract(BigDecimal.valueOf(DEDUCTIBLE_PER_DAMAGE_IN_G));
    57	    }
    58	
    59	    /**
    60	     * How much of a reported damage the MHPCO reimburses, before the
    61	     * deductible: damage to a volatile item is reimbursed at half, anything
    62	     * else in full.
    63	     */
    64	    private static BigDecimal reimbursableAmount(Damage damage, Item damagedItem) {
    65	        if (isVolatile(damagedItem)) {
    66	            return Percentage.of(damage.amount(), VOLATILE_ITEM_REIMBURSEMENT_PERCENT);
    67	        }
    68	        return BigDecimal.valueOf(damage.amount());
    69	    }
    70	
    71	    /**
    72	     * The MHPCO counts an item of enchantment level 8 or more as volatile:
    73	     * too unstable to reimburse in full, whatever it is made of.
    74	     */
    75	    private static boolean isVolatile(Item item) {
    76	        return item.enchantment() >= VOLATILE_ENCHANTMENT_LEVEL;
    77	    }
    78	}
